"""Stage 14: overlapping patch-embedding, within-image 5th neighbor.

Frozen DINOv2 patch projection only. Stride 7 on the 672 crop, no transformer
and no trained head. Score at each location is 1 minus the cosine similarity
of the 5th nearest token outside a radius-2 neighborhood in the same image.

B0 is stage-7 guide_fuse672. The pass rule uses the unfused high-res map only:
screw and capsule strictly above B0, leather and grid drop by at most 2pp,
four-class macro gain at least 2pp. Fusion is not part of the rule.

Kaggle executes this file from read-only /kaggle/src. The stage-12 helper is
embedded below and written to /kaggle/working.
"""
import os
import sys
import time
import argparse

import numpy as np
import torch
import torch.nn.functional as F


SLUG = "eunectesqaq/dinomaly-hires-knn-v14"
KERNEL = 14
STRIDE = 7
K_NEIGHBOR = 5
RADIUS = 2
CLASSES = ("leather", "capsule", "grid", "screw")
OUT = "/kaggle/working"


def grid_size(image, kernel=KERNEL, stride=STRIDE):
    return (int(image) - kernel) // stride + 1


def within_image_knn(feat, k=K_NEIGHBOR, radius=RADIUS):
    """feat [B,C,H,W] -> distance [B,H,W].

    Distance is 1 minus the k-th highest cosine similarity outside the
    Chebyshev neighborhood. Masked positions are set below any real cosine.
    """
    b, _c, h, w = feat.shape
    n = h * w
    flat = F.normalize(feat.flatten(2).transpose(1, 2), dim=-1)
    sim = flat @ flat.transpose(1, 2)
    ys = torch.arange(h, device=feat.device)
    xs = torch.arange(w, device=feat.device)
    yy = ys.view(h, 1, 1, 1)
    xx = xs.view(1, w, 1, 1)
    y2 = ys.view(1, 1, h, 1)
    x2 = xs.view(1, 1, 1, w)
    local = ((yy - y2).abs() <= radius) & ((xx - x2).abs() <= radius)
    sim = sim.masked_fill(local.reshape(1, n, n), -2.0)
    kth = sim.topk(k, dim=-1).values[:, :, -1]
    return (1.0 - kth).reshape(b, h, w)


def overlapping_embed(proj, images, stride=STRIDE):
    feat = F.conv2d(images, proj.weight, proj.bias, stride=stride, padding=0)
    expected = grid_size(images.shape[-1], proj.weight.shape[-1], stride)
    if feat.shape[-1] != expected or feat.shape[-2] != expected:
        raise RuntimeError(
            f"embed grid {tuple(feat.shape[-2:])} != {expected}")
    return feat


def decide(per_class):
    """Frozen before any stage-14 score. per_class[name] = {'b0','hires'} P-AP."""
    needed = ("leather", "capsule", "grid", "screw")
    deltas = {c: per_class[c]["hires"] - per_class[c]["b0"] for c in needed}
    macro = float(sum(deltas.values()) / len(deltas))
    passed = bool(
        deltas["screw"] > 0.0
        and deltas["capsule"] > 0.0
        and deltas["leather"] >= -0.02
        and deltas["grid"] >= -0.02
        and macro >= 0.02)
    return {
        "passed": passed,
        "macro_hires_minus_b0": macro,
        "per_class_hires_minus_b0": deltas,
        "rule": {
            "screw_and_capsule": "strictly above b0",
            "leather_and_grid_floor": -0.02,
            "macro_gain_min": 0.02,
            "fusion_counts": False,
        },
    }


def first_writable(candidates):
    for folder in candidates:
        if not folder or not os.path.isdir(folder):
            continue
        probe = os.path.join(folder, ".stage14_write_probe")
        try:
            with open(probe, "w", encoding="utf-8") as handle:
                handle.write("ok")
            os.remove(probe)
            return folder
        except OSError:
            continue
    return None


def _import_stage12():
    here = os.path.dirname(os.path.abspath(__file__))
    sibling = os.path.abspath(os.path.join(
        here, "..", "stage12", "masked_recon_v12.py"))
    if os.path.isfile(sibling):
        sys.path.insert(0, os.path.dirname(sibling))
    else:
        import base64
        import zlib
        raw = zlib.decompress(base64.b64decode(_STAGE12_ZLIB))
        folder = first_writable([
            "/kaggle/working",
            os.environ.get("TMPDIR", ""),
            os.environ.get("TEMP", ""),
            os.environ.get("TMP", ""),
        ])
        if folder is None:
            raise OSError("no writable directory for the stage-12 helper")
        dest = os.path.join(folder, "masked_recon_v12.py")
        with open(dest, "wb") as handle:
            handle.write(raw)
        sys.path.insert(0, folder)
        print(f"[stage14] materialized stage12 helper at {dest}", flush=True)
    import masked_recon_v12 as stage12
    return stage12


_STAGE12_ZLIB = """"""
s12 = _import_stage12()


def log(msg):
    s12.log(msg)


def run_self_test():
    checks = 0

    def ok(cond, msg):
        nonlocal checks
        if not cond:
            raise AssertionError(msg)
        checks += 1

    ok(grid_size(672) == 95, "672 / stride 7 is a 95 grid")
    ok(grid_size(392, stride=14) == 28, "native stride still matches 392")

    normal = torch.zeros(1, 4, 8, 8)
    normal[:, 0] = 1.0
    odd = normal.clone()
    odd[0, :, 3, 4] = 0.0
    odd[0, 1, 3, 4] = 1.0
    score = within_image_knn(odd, k=5, radius=1)
    ok(float(score[0, 3, 4]) > 0.9, "odd token is far from the image")
    ok(float(score[0, 0, 0]) < 0.05, "repeated token matches other copies")
    # A token must not be allowed to match itself: radius 0 still covers it.
    eye = within_image_knn(odd, k=1, radius=0)
    ok(float(eye[0, 3, 4]) > 0.9, "radius 0 still excludes the token itself")

    good = {
        "leather": {"b0": 0.50, "hires": 0.53},
        "capsule": {"b0": 0.60, "hires": 0.62},
        "grid": {"b0": 0.55, "hires": 0.54},
        "screw": {"b0": 0.60, "hires": 0.66},
    }
    decision = decide(good)
    ok(decision["passed"] is True, "synthetic pass")
    bad = {k: dict(v) for k, v in good.items()}
    bad["screw"]["hires"] = 0.59
    ok(decide(bad)["passed"] is False, "screw below b0 fails")
    dust = {k: dict(v) for k, v in good.items()}
    dust["capsule"]["hires"] = 0.605
    dust["screw"]["hires"] = 0.605
    dust["leather"]["hires"] = 0.505
    dust["grid"]["hires"] = 0.555
    ok(decide(dust)["passed"] is False, "macro under 2pp fails")

    import base64
    import hashlib
    import zlib
    sibling = os.path.abspath(os.path.join(
        os.path.dirname(__file__), "..", "stage12", "masked_recon_v12.py"))
    vendored = zlib.decompress(base64.b64decode(_STAGE12_ZLIB))
    ok(b"def stage7_reference_b0" in vendored, "vendored helper contains B0")
    if os.path.isfile(sibling):
        with open(sibling, "rb") as handle:
            on_disk = handle.read()
        ok(hashlib.sha256(vendored).digest() == hashlib.sha256(on_disk).digest(),
           "vendored stage12 matches the sibling file")
    folder = first_writable([os.environ.get("TEMP", ""), "/kaggle/working"])
    ok(folder is not None, "a writable directory exists")
    log(f"self-test passed checks={checks}")
    return checks


def score_batch(model, proj, x_base, x_hi, gaussian):
    with torch.no_grad():
        b0 = s12.stage7_reference_b0(model, x_base, x_hi, gaussian)
        feat = overlapping_embed(proj, x_hi)
        hires = s12.postprocess(
            within_image_knn(feat).unsqueeze(1), gaussian)
    return b0, hires


def evaluate_class(item, dataset, model, proj, gaussian, device):
    loader = s12.DataLoader(dataset, batch_size=1, shuffle=False, num_workers=0)
    maps = {"b0": [], "hires": []}
    scores = {"b0": [], "hires": []}
    gt_buf, labels = [], []
    started = time.time()
    for bi, batch in enumerate(loader):
        img, gt, label, _path, his = batch
        img = img.to(device)
        his = his.to(device)
        b0, hires = score_batch(model, proj, img, his, gaussian)
        for name, tensor in (("b0", b0), ("hires", hires)):
            maps[name].append(tensor.cpu())
            scores[name].extend(s12.top1pct(tensor).cpu().numpy().tolist())
        gt256 = torch.nn.functional.interpolate(
            gt.float(), size=256, mode="nearest").bool()
        if gt256.shape[1] > 1:
            gt256 = gt256.max(dim=1, keepdim=True).values
        gt_buf.append(gt256.cpu())
        labels.extend(label.numpy().tolist())
        del img, his, b0, hires
        if bi == 0 or (bi + 1) == len(loader) or (bi + 1) % 20 == 0:
            log(f"  {item} {bi + 1}/{len(loader)}")
    gt_np = torch.cat(gt_buf, dim=0)[:, 0].numpy()
    gt_np = (gt_np > 0.5).astype(np.uint8)
    labels_np = np.asarray(labels, dtype=np.int64)
    regions = s12.label_regions(gt_np)
    variants = {}
    for name in ("b0", "hires"):
        pr = torch.cat(maps[name], dim=0)[:, 0].numpy().astype(np.float32)
        img_metrics = s12.image_metrics_from_scores(
            labels_np, np.asarray(scores[name]))
        variants[name] = s12.summarize_variant(
            gt_np, pr, labels_np, img_metrics, regions)
    return {
        "class": item,
        "n_test": int(len(labels_np)),
        "n_anomaly": int((labels_np == 1).sum()),
        "n_gt_positive_pixels": int(gt_np.sum()),
        "seconds": float(time.time() - started),
        "variants": {
            name: {"metrics": variants[name]["metrics"],
                   "recall": variants[name]["recall"],
                   "per_image_ap": [
                       (float(x) if np.isfinite(x) else None)
                       for x in variants[name]["per_image_ap"]]}
            for name in ("b0", "hires")
        },
    }


def main():
    global OUT
    ap = argparse.ArgumentParser()
    ap.add_argument("--self-test", action="store_true")
    ap.add_argument("--classes", type=str, default=",".join(CLASSES))
    ap.add_argument("--out", type=str, default=None)
    ap.add_argument("--limit-test", type=int, default=0)
    args = ap.parse_args()
    if args.self_test:
        s12.LOG_PATH = None
        run_self_test()
        return

    OUT = os.path.abspath(args.out or (
        "/kaggle/working" if os.path.isdir("/kaggle/working")
        else os.path.join(os.path.dirname(__file__), "..", "..", "stage14-local")))
    os.makedirs(OUT, exist_ok=True)
    s12.LOG_PATH = os.path.join(OUT, "stage14.log")
    log(f"=== {SLUG} start ===")
    run_self_test()

    s12.prepare_environment()
    device = "cuda:0" if torch.cuda.is_available() else "cpu"
    if device == "cpu":
        raise RuntimeError("stage 14 needs a GPU")
    s12.BASE_BATCH_EFF = 1
    s12.HI_BATCH_EFF = 1
    s12.EVAL_BATCH = 1
    torch.manual_seed(1)
    torch.cuda.manual_seed_all(1)

    s12.find_checkpoints()
    base_sha = s12.sha256_file(s12.BASE_CKPT)
    log(f"base sha256={base_sha}")
    model = s12.build_model(device)
    state = s12.load_ckpt(model, s12.BASE_CKPT, device)
    model.eval()
    for p in model.parameters():
        p.requires_grad_(False)
    proj = model.encoder.patch_embed.proj
    log(f"checkpoint iter={state.get('iter')} proj={tuple(proj.weight.shape)} "
        f"stride={STRIDE} k={K_NEIGHBOR} radius={RADIUS}")

    base_tf, gt_tf = s12.get_data_transforms(s12.BASE_RESIZE, s12.BASE_CROP)
    hi_tf = s12.get_data_transforms(s12.HI_RESIZE, s12.HI_CROP)[0]
    gaussian = s12.get_gaussian_kernel(
        kernel_size=s12.GAUSSIAN_KERNEL, sigma=s12.GAUSSIAN_SIGMA).to(device)

    items = [c.strip() for c in args.classes.split(",") if c.strip()]
    per_class = {}
    for item in items:
        ds = s12.MultiScaleTestDataset(
            os.path.join(s12.DATA, item), base_tf, gt_tf, hi_tf)
        if args.limit_test:
            ds.base.img_paths = ds.base.img_paths[:args.limit_test]
            ds.base.gt_paths = ds.base.gt_paths[:args.limit_test]
            ds.base.labels = ds.base.labels[:args.limit_test]
            ds.base.types = ds.base.types[:args.limit_test]
        elif item in s12.EXPECTED_TEST_IMAGES and len(ds) != s12.EXPECTED_TEST_IMAGES[item]:
            raise RuntimeError(
                f"{item}: expected {s12.EXPECTED_TEST_IMAGES[item]} images, got {len(ds)}")
        result = evaluate_class(item, ds, model, proj, gaussian, device)
        per_class[item] = result
        s12.write_json_atomic(os.path.join(OUT, f"{item}.json"), result)
        b0 = result["variants"]["b0"]["metrics"]["P-AP"]
        hi = result["variants"]["hires"]["metrics"]["P-AP"]
        ref = s12.STAGE7_REFERENCE.get(item, {}).get("P-AP")
        log(f"{item} n={result['n_test']} b0={b0:.4f} hires={hi:.4f} "
            f"delta={hi - b0:+.4f} stage7_b0={ref}")

    if set(items) == set(CLASSES):
        flat = {c: {k: per_class[c]["variants"][k]["metrics"]["P-AP"]
                    for k in ("b0", "hires")} for c in CLASSES}
        decision = decide(flat)
    else:
        decision = {"passed": None, "note": "partial class list, rule not applied"}
    identity = {}
    for item, result in per_class.items():
        ref = s12.STAGE7_REFERENCE.get(item)
        if not ref:
            continue
        got = result["variants"]["b0"]["metrics"]["P-AP"]
        identity[item] = got - ref["P-AP"]
    report = {
        "experiment": {
            "slug": SLUG,
            "stage": 14,
            "idea": "stride-7 frozen patch embedding, within-image 5th neighbor",
            "base_sha256": base_sha,
        },
        "config": {
            "classes": items,
            "kernel": KERNEL,
            "stride": STRIDE,
            "k": K_NEIGHBOR,
            "radius": RADIUS,
            "grid": grid_size(672),
            "trained": False,
        },
        "b0_minus_stage7_P-AP": identity,
        "per_class": per_class,
        "decision": decision,
    }
    s12.write_json_atomic(os.path.join(OUT, "hires_knn_report.json"), report)
    log(f"decision={decision}")
    log("=== stage14 done ===")


if __name__ == "__main__":
    main()
